from flask import Flask, request, send_file
import os
from werkzeug.utils import secure_filename

app = Flask(__name__)
IMAGE_DIR = '/path/to/images'

def load(file_path):
    # Load the file in binary mode
    return open(file_path, 'rb')

@app.route('/img')
def img():
    filename = request.args.get('file')
    if not filename:
        return 'No file specified', 400

    safe_filename = secure_filename(filename)
    file_path = os.path.realpath(os.path.join(IMAGE_DIR, safe_filename))

    # Path traversal protection
    if not file_path.startswith(os.path.realpath(IMAGE_DIR)):
        return "Forbidden", 403

    file_handle = load(file_path)
    return send_file(file_handle, mimetype='image/jpeg')
