import subprocess

urls = {}

def route(url):
    def decorator(f):
        urls[url] = f
        return f
    return decorator

@route('/ping/<url>')
def ping(url):
    """
    Runs the system ping command on the provided URL and returns the output.
    """
    try:
        output = subprocess.check_output(['ping', '-c', '4', url], stderr=subprocess.STDOUT)
    except subprocess.CalledProcessError as e:
        output = e.output
    return output
