import subprocess
import sys

def ping_domain(domain):
    """
    Perform a DNS lookup for the provided domain using the dig command.
    """
    try:
        result = subprocess.run(['dig', domain, '+short'], capture_output=True, text=True, check=True)
        if result.stdout:
            print(result.stdout.strip())
        else:
            print("No records found.")
    except subprocess.CalledProcessError as e:
        print(f"Error executing dig: {e}", file=sys.stderr)
        sys.exit(1)
    except FileNotFoundError:
        print("Error: 'dig' command not found. Please install dnsutils.", file=sys.stderr)
        sys.exit(1)
