import json
import yaml
import os
from flask import Flask, request

app = Flask(__name__)
CACHE_DIR = 'cache'

if not os.path.exists(CACHE_DIR):
    os.makedirs(CACHE_DIR)

def reconstruct_object(file_content):
    try:
        return json.loads(file_content)
    except json.JSONDecodeError:
        try:
            return yaml.safe_load(file_content)
        except yaml.YAMLError:
            return None

def write_json_to_file(path, data):
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(data, f)

@app.route('/upload', methods=['POST'])
def upload_file():
    if 'file' not in request.files:
        return 'No file part', 400

    file = request.files['file']
    if file.filename == '':
        return 'No selected file', 400

    file_content = file.read()
    obj = reconstruct_object(file_content)

    if obj is None:
        return 'Invalid file format', 400

    cache_path = os.path.join(CACHE_DIR, file.filename + '.json')
    write_json_to_file(cache_path, obj)

    return 'File processed and cached successfully', 200
