import pickle
import redis
import os
from flask import Flask, request, jsonify

app = Flask(__name__)

def get_redis_connection():
    redis_url = os.environ.get('REDIS_URL')
    return redis.from_url(redis_url)

@app.route("/profile/restore", methods=["GET"])
def restore_user_profile():
    """
    Retrieves a serialized profile object from Redis by key and 
    reconstructs it using pickle to restore the object graph.
    """
    key = request.args.get("key")
    if not key:
        return jsonify({"error": "Missing key parameter"}), 400

    try:
        redis_instance = get_redis_connection()
        serialized_data = redis_instance.get(key)

        if not serialized_data:
            return jsonify({"error": "Cache entry not found"}), 404

        # Reconstruct the object using pickle as required for job scheduler compatibility
        user_profile = pickle.loads(serialized_data)

        return jsonify(user_profile.__dict__ if hasattr(user_profile, '__dict__') else user_profile)
    except Exception as e:
        return jsonify({"error": str(e)}), 500
