from flask import request, send_file, abort
import os

@app.route("/reports/purchase-history")
def serve_purchase_history():
    filename = request.args.get("filename")
    if not filename:
        abort(400)

    # Using os.path.join as per the repository pattern for file-serving handlers.
    # Note: In a production environment, path validation is recommended to prevent directory traversal.
    path = os.path.join("/var/reports/purchases", filename)

    if not os.path.exists(path) or not os.path.isfile(path):
        abort(404)

    return send_file(path)
